std::span<const TypeDescriptor> TypeDescriptors() {
    return kTypeDescriptors;
}

std::span<const StreamDescriptor> StreamDescriptors() {
    return kStreamDescriptors;
}

std::span<const TableDescriptor> TableDescriptors() {
    return kTableDescriptors;
}

std::span<const FieldDescriptor> FieldDescriptors() {
    return kFieldDescriptors;
}

const TypeDescriptor* FindTypeByToken(std::string_view type_token) {
    for (const auto& descriptor : kTypeDescriptors) {
        if (descriptor.type_token == type_token) {
            return &descriptor;
        }
    }
    return nullptr;
}

const StreamDescriptor* FindStreamByCode(StreamCode stream_code) {
    for (const auto& descriptor : kStreamDescriptors) {
        if (descriptor.stream_code == stream_code) {
            return &descriptor;
        }
    }
    return nullptr;
}

const TableDescriptor* FindTableByCode(TableCode table_code) {
    for (const auto& descriptor : kTableDescriptors) {
        if (descriptor.table_code == table_code) {
            return &descriptor;
        }
    }
    return nullptr;
}

const FieldDescriptor* FindFieldByCode(FieldCode field_code) {
    for (const auto& descriptor : kFieldDescriptors) {
        if (descriptor.field_code == field_code) {
            return &descriptor;
        }
    }
    return nullptr;
}

std::span<const TableDescriptor> TablesForStream(StreamCode stream_code) {
    const auto* stream = FindStreamByCode(stream_code);
    if (stream == nullptr) {
        return {};
    }
    return std::span<const TableDescriptor>(
        kTableDescriptors.data() + stream->first_table_index,
        stream->table_count);
}

std::span<const FieldDescriptor> FieldsForTable(TableCode table_code) {
    const auto* table = FindTableByCode(table_code);
    if (table == nullptr) {
        return {};
    }
    return std::span<const FieldDescriptor>(
        kFieldDescriptors.data() + table->first_field_index,
        table->field_count);
}

